using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using UnityEditor;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class CDPlay {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string O=>R+"/Docs/Review/2026-11-10_B2_CeilingDensity/";
 static GameObject player;static PlayerMotor motor;static PlayerLook look;static CharacterController cc;static Vector3 savedPos;static Quaternion savedRot;static bool savedLook,running;static int stage,index,firstFrame,moveEvents;static float startTime;static double wallStart;static Vector3[] points;static List<object> rows=new List<object>();static List<string> errors=new List<string>();static InputSettings.BackgroundBehavior bg;static InputSettings.EditorInputBehaviorInPlayMode eb;static InputAction move;static JObject plan;static string label;static bool crouch;static Vector3 from;
 public static object Prepare(){if(Application.isPlaying)throw new Exception("Edit mode required");SessionState.SetBool("CDPlay.Background",Application.runInBackground);Application.runInBackground=true;return new{Mouse.current.enabled,keyboard=Keyboard.current.enabled};}
 public static object Begin(){if(!Application.isPlaying||!SceneManager.GetActiveScene().path.EndsWith("Level_B2_Circular.unity"))throw new Exception("B2 Play required");player=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));motor=player.GetComponent<PlayerMotor>();look=player.GetComponent<PlayerLook>();cc=player.GetComponent<CharacterController>();savedPos=player.transform.position;savedRot=player.transform.rotation;savedLook=look.enabled;look.enabled=false;bg=InputSystem.settings.backgroundBehavior;eb=InputSystem.settings.editorInputBehaviorInPlayMode;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.GameView")).Focus();plan=JObject.Parse(File.ReadAllText(R+"/SourceAssets/B2_CeilingDensity/plan.json"));rows.Clear();errors.Clear();moveEvents=0;move=player.GetComponent<PlayerInput>().actions.FindAction("Player/Move",true);move.performed+=ReadMove;stage=0;running=true;Next();InputSystem.onAfterUpdate+=Input;EditorApplication.update+=Tick;Application.logMessageReceived+=Log;AssemblyReloadEvents.beforeAssemblyReload+=Cancel;EditorApplication.playModeStateChanged+=Mode;return new{started=true,stages=8,frame=Time.frameCount};}
 static void ReadMove(InputAction.CallbackContext c){moveEvents++;}static void Log(string m,string st,LogType t){if(t==LogType.Error||t==LogType.Exception)errors.Add(m);}static void Mode(PlayModeStateChange m){if(m==PlayModeStateChange.ExitingPlayMode)Cancel();}static void Cancel(){if(running)End(false);}
 static void Next(){string room;Vector3[] local;crouch=false;
if(stage<6){room=new[]{"C02","C01","W02","S01","E03","N01"}[stage];label=room+" resized equipment aisle";
var routes=new[]{
 new[]{new Vector3(0,0,-7),new Vector3(0,0,3.9f)},
 new[]{new Vector3(0,0,-6),new Vector3(0,0,3.6f)},
 new[]{new Vector3(.5f,0,-4.6f),new Vector3(.5f,0,3.1f)},
 new[]{new Vector3(0,0,-4.5f),new Vector3(0,0,2.5f)},
 new[]{new Vector3(-5.4f,0,0),new Vector3(1.5f,0,0),new Vector3(1.5f,0,3.3f)},
 new[]{new Vector3(0,0,-4),new Vector3(0,0,4.2f)}};local=routes[stage];
}else{label=new[]{"C02_Stair_0","E01_Stair_1"}[stage-6];var route=plan["routes"].Single(r=>(string)r["name"]==label);room=(string)route["room"];local=route["points"].Select(p=>new Vector3((float)p[0],(float)p[1],(float)p[2])).ToArray();crouch=(float)route["height"]<1.5f;}
var r=plan["rooms"].Single(r=>(string)r["id"]==room);var origin=new Vector3((float)r["x"],-34,-(float)r["v"]);points=local.Select(p=>p+origin).ToArray();cc.enabled=false;player.transform.position=origin+new Vector3(0,1.5f,0);cc.enabled=true;motor.TryStandUp();if(crouch)motor.Crouch();cc.enabled=false;player.transform.position=points[0]+Vector3.up*(cc.height/2-cc.center.y+.04f);player.transform.rotation=Quaternion.LookRotation(new Vector3(points[1].x-points[0].x,0,points[1].z-points[0].z));cc.enabled=true;Physics.SyncTransforms();if(!crouch&&!motor.TryStandUp())throw new Exception("Standing start blocked: "+label);typeof(PlayerMotor).GetField("verticalVelocity",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(motor,0f);from=player.transform.position;index=1;firstFrame=Time.frameCount;startTime=Time.time;wallStart=EditorApplication.timeSinceStartup;}
 static void Input(){if(running&&InputState.currentUpdateType!=InputUpdateType.Editor)InputState.Change(Keyboard.current,Time.time-startTime>.3f&&index<points.Length?new KeyboardState(Key.W):new KeyboardState());}
 static void Tick(){try{if(!Application.isPlaying){End(false);return;}EditorApplication.QueuePlayerLoopUpdate();float elapsed=Time.time-startTime;var goal=points[Math.Min(index,points.Length-1)];var delta=goal-player.transform.position;delta.y=0;if(elapsed>.3f&&index<points.Length){if(delta.magnitude<.18f){index++;if(index<points.Length)delta=points[index]-player.transform.position;}delta.y=0;if(delta.sqrMagnitude>.001f)player.transform.rotation=Quaternion.LookRotation(delta);}
 if(index<points.Length&&elapsed<16&&EditorApplication.timeSinceStartup-wallStart<30)return;if(index>=points.Length&&Time.frameCount-firstFrame<25)return;float feet=player.transform.position.y+cc.center.y-cc.height/2;float error=Math.Abs(feet-points.Last().y);bool pass=index>=points.Length&&Time.frameCount-firstFrame>20&&error<.30f&&errors.Count==0;rows.Add(new{name=label,passed=pass,frames=Time.frameCount-firstFrame,time=elapsed,feetError=error,remaining=delta.magnitude,waypoints=index,expectedWaypoints=points.Length,crouching=motor.IsCrouching,moveEvents});stage++;if(stage<8)Next();else End(true);
 }catch(Exception e){errors.Add(e.ToString());End(false);}}
 static void End(bool complete){running=false;InputSystem.onAfterUpdate-=Input;EditorApplication.update-=Tick;Application.logMessageReceived-=Log;AssemblyReloadEvents.beforeAssemblyReload-=Cancel;EditorApplication.playModeStateChanged-=Mode;if(move!=null)move.performed-=ReadMove;try{InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState());File.WriteAllText(O+"play.json",JsonConvert.SerializeObject(new{complete,results=rows,errors,mouse=Mouse.current.enabled,keyboard=Keyboard.current.enabled},Formatting.Indented));}finally{InputSystem.settings.backgroundBehavior=bg;InputSystem.settings.editorInputBehaviorInPlayMode=eb;if(player){cc.enabled=false;player.transform.SetPositionAndRotation(savedPos,savedRot);cc.enabled=true;motor.TryStandUp();}if(look)look.enabled=savedLook;}}
 public static object Restore(){if(Application.isPlaying)throw new Exception("Exit Play first");Application.runInBackground=SessionState.GetBool("CDPlay.Background",false);return new{mouse=Mouse.current.enabled,keyboard=Keyboard.current.enabled,Application.runInBackground,dirty=SceneManager.GetActiveScene().isDirty};}
}
